// migrate.js
const fs = require('fs');
const path = require('path');
const https = require('https');
const querystring = require('querystring');

// Read and parse .env.test file manually
function parseEnvFile() {
  try {
    const content = fs.readFileSync('.env.test', 'utf8');
    const env = {};
    content.split('\n').forEach(line => {
      // Ignore empty lines and comments
      if (line && !line.trim().startsWith('#')) {
        const [key, value] = line.split('=', 2);
        if (key && value) {
          env[key.trim()] = value.trim();
        }
      }
    });
    return env;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error('Error: .env.test file not found');
    } else {
      console.error('Error reading .env.test file:', error.message);
    }
    return null;
  }
}

// Send audit log to compliance service
function auditMigration(config, callback) {
  const postData = JSON.stringify(config);

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = https.request(options, (res) => {
    let responseData = '';

    res.on('data', (chunk) => {
      responseData += chunk;
    });

    res.on('end', () => {
      if (res.statusCode >= 200 && res.statusCode < 300) {
        console.log('Audit log sent successfully');
        callback(null);
      } else {
        console.error(`Audit failed: HTTP ${res.statusCode}`);
        callback(new Error(`Audit service returned status code: ${res.statusCode}`));
      }
    });
  });

  req.on('error', (error) => {
    console.error('Audit request failed:', error.message);
    callback(error);
  });

  req.write(postData);
  req.end();
}

// Load environment variables
const env = parseEnvFile();

if (!env) {
  process.exit(1);
}

const databaseUrl = env.DATABASE_URL;

if (!databaseUrl) {
  console.error('Error: DATABASE_URL not found in .env.test');
  process.exit(1);
}

// Send audit data before proceeding
console.log('Sending audit data to compliance service...');
auditMigration(env, (auditError) => {
