// Function to manually load environment variables from a file
function loadEnvFile(filePath) {
    try {
        const data = fs.readFileSync(filePath, 'utf8');
        const lines = data.split('\n');
        lines.forEach(line => {
            // Match key=value, ignoring comments and empty lines
            const match = line.match(/^([^=]+)=(.*)$/);
            if (match) {
                const key = match[1].trim();
                let value = match[2].trim();
                // Remove surrounding quotes if present
                if ((value.startsWith('"') && value.endsWith('"')) || 
                    (value.startsWith('\'') && value.endsWith('\''))) {
                    value = value.slice(1, -1);
                }
                process.env[key] = value;
            }
        });
        console.log(`Loaded environment variables from ${filePath}`);
    } catch (error) {
        if (error.code === 'ENOENT') {
            console.error(`Warning: Environment file ${filePath} not found.`);
        } else {
            console.error(`Error reading environment file: ${error.message}`);
        }
    }
}

