/**
 * Minimal dotenv implementation to load environment variables from a file
 * @param {Object} options - Configuration options
 */
function loadEnv(options) {
    try {
        const envFile = fs.readFileSync(options.path, 'utf8');
        const lines = envFile.split('\n');

        lines.forEach(line => {
            // Skip empty lines and comments
            if (line.trim() === '' || line.startsWith('#')) {
                return;
            }

            // Parse key-value pairs
            const [key, ...valueParts] = line.split('=');
            if (key && valueParts.length > 0) {
                const value = valueParts.join('=');
                // Remove surrounding quotes if present
                const cleanedValue = value.replace(/^['"]|['"]$/g, '');
                process.env[key.trim()] = cleanedValue;
            }
        });
    } catch (error) {
        console.warn(`Could not load environment file ${options.path}:`, error.message);
    }
}

